INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (1, '赵州桥建成', '隋朝大业年间 (公元 605-618 年),著名工匠李春设计建造赵州桥。赵州桥是世界上现存最古老、跨度最大的单孔敞肩石拱桥，开创了世界桥梁史上的先河。', 'zhaozhouqiao.png', 'https://baike.baidu.com/item/赵州桥/107418', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (2, '卢沟桥事变', '1937 年 7 月 7 日，日本侵略军在北平西南卢沟桥附近演习时，借口一名士兵\"失踪\",要求进入宛平县城搜查，遭到中国守军第 29 军严词拒绝。日军遂向中国守军开枪射击，又炮轰宛平城。第 29 军奋起抗战。这就是震惊中外的\"七七事变\",又称\"卢沟桥事变\"。', 'lugouqiao.jpg', 'https://baike.baidu.com/item/卢沟桥事变/109429', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (3, '洛阳桥建成', '北宋皇祐五年 (1053 年),泉州太守蔡襄主持建造洛阳桥。洛阳桥是中国第一座跨海梁式石桥，首创\"筏形基础\"和\"种蛎固基\"技术，在世界桥梁史上具有重要地位。', 'luoyangqiao.jpg', 'https://baike.baidu.com/item/洛阳桥/10709', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (4, '飞夺泸定桥', '1935 年 5 月 29 日，中国工农红军长征途中，红四团战士在四川泸定桥面对敌人拆除木板、只剩铁索的险境，22 名勇士冒着枪林弹雨攀爬铁索，成功夺取泸定桥，为红军主力北上开辟了道路。', 'yuzhaofeiliang.jpg', 'https://baike.baidu.com/item/飞夺泸定桥/109428', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (5, '南京长江大桥建成', '1968 年 12 月 29 日，南京长江大桥全面建成通车。这是中国自行设计和建造的第一座双层式铁路、公路两用桥，是新中国桥梁建设史上的里程碑。', 'qinhan.jpg', 'https://baike.baidu.com/item/南京长江大桥/10710', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (6, '马可波罗记载卢沟桥', '1275 年，意大利旅行家马可波罗来到中国，在其《马可波罗游记》中详细记载了卢沟桥的雄伟壮观，称其为\"世界上最好的、独一无二的桥\",使卢沟桥闻名欧洲。', 'lugouqiao.jpg', 'https://baike.baidu.com/item/马可波罗游记/109430', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (7, '宝带桥重建', '唐元和十一年 (816 年),苏州刺史王仲舒捐宝带资助重建宝带桥。宝带桥全长 317 米，53 孔，是中国现存最长的多孔古石桥，也是世界文化遗产大运河的重要组成部分。', 'baodaiqiao.jpg', 'https://baike.baidu.com/item/宝带桥/10709', '2026-04-28 15:37:10');
INSERT INTO `bridge_events` (`id`, `title`, `description`, `img`, `url`, `create_time`) VALUES (8, '广济桥建成', '南宋乾道七年 (1171 年),广济桥在潮州建成。广济桥全长 518 米，集梁桥、浮桥、拱桥于一体，被誉为\"世界上最早的启闭式桥梁\",是中国古桥建筑的杰作。', 'guangjiqiao.jpg', 'https://baike.baidu.com/item/广济桥/10710', '2026-04-28 15:37:10');
